// Package publishsubmittedcarts is the automation "publish submitted carts".
// It works off the "Carts To Publish" todo list and sends
// "Publish Cart" for every row.
package publishsubmittedcarts

import (
	"context"

	"github.com/terraskye/eventsourcing"
	"github.com/terraskye/eventsourcing/automation"

	"example.com/cart/slices/cartstopublish"
	"example.com/cart/slices/publishcart"
)

// NewAutomation returns the automation. todoList is the runner of the todo
// list's projection, so that the automation only claims rows while the list
// is live.
func NewAutomation(
	list *cartstopublish.CartsToPublish,
	todoList automation.Dependency,
	handler eventsourcing.CommandHandler[publishcart.PublishCart],
) automation.Definition[cartstopublish.Row] {
	return automation.Definition[cartstopublish.Row]{
		Name:     "publish-submitted-carts",
		TodoList: todoList,
		Claim:    list.Claim,
		// Work runs at least once per row: the command must be safe to
		// repeat, which decide makes it by recording nothing the second time.
		Work: func(ctx context.Context, item cartstopublish.Row) error {
			_, err := handler(ctx, publishcart.PublishCart{
				CartID: item.CartID,
			})
			return err
		},
	}
}
